const data = $input.first().json;

const groups = {
  '【①預約】':  ['預約_總數','預約_完成','預約_未到','預約_備註'],
  '【②財務】':  ['財務_收入','財務_完成率','財務_未完成','財務_備註'],
  '【③護道會】':['護道會_關懷','護道會_約定','護道會_備註'],
  '【④志工】':  ['志工_項目','志工_出勤','志工_備註'],
  '【⑤來客】':  ['來客_總數','來客_新結緣','來客_來源','來客_備註'],
  '【⑥活動】':  ['活動_項目','活動_推展','活動_報名','活動_備註'],
  '【⑦修法】':  ['修法_項目','修法_推展','修法_報名','修法_備註'],
  '【⑧平台】':  ['平台_登入','平台_待辦','平台_紅字','平台_備註'],
  '【⑨法事】':  ['法事_七天前','法事_明天','法事_今日','法事_備註'],
  '【⑩供餐】':  ['供餐_廚師','供餐_預定','供餐_實際','供餐_備註'],
  '【⑪經典】':  ['經典_名稱','經典_發送','經典_誦讀','經典_備註'],
  '【⑫點燈】':  ['點燈_名稱','點燈_人數','點燈_修法','點燈_備註'],
  '【⑬生日】':  ['生日_平台','生日_關懷','生日_祈福','生日_備註'],
  '【⑭公關】':  ['公關_七天前','公關_明日','公關_今日','公關_備註'],
  '【⑮媒體】':  ['媒體_七天前','媒體_明日','媒體_今日','媒體_備註'],
  '【⑯數位】':  ['數位_七天前','數位_明日','數位_今日','數位_備註'],
  '【⑰商學院】':['商學院_關懷','商學院_報名','商學院_約定','商學院_備註'],
  '【⑱五常】':  ['五常_重點','五常_會務','五常_執行','五常_備註'],
  '【⑲醫方明】':['醫方明_重點','醫方明_調護','醫方明_報名','醫方明_備註'],
  '【⑳修繕】':  ['修繕_三天前','修繕_明日','修繕_今日','修繕_備註'],
  '【㉑侍神】':  ['侍神_重點','侍神_邀請','侍神_參與','侍神_備註'],
  '【㉒採購】': ['採購_內容','採購_金額','採購_次數','採購_備註'],
};

let lines = [];
lines.push( data['姓名'] + ' 每日工作記錄｜' + data['日期']);
lines.push('═══════');

for (const [groupName, keys] of Object.entries(groups)) {
  const groupLines = [];
  for (const key of keys) {
    const val = data[key];
    if (val === 0 || val === '' || val === null || val === undefined) continue;
    const label = key.includes('_') ? key.split('_')[1] : key;
    groupLines.push(`  ${label}：${val}`);
  }
  if (groupLines.length > 0) {
    lines.push(groupName);
    lines.push(...groupLines);
  }
}

lines.push('═══════');
return [{ json: { message: lines.join('\n') } }];

